Here are the available function definitions you can call:

```json
{
  "generate_image_tool": {
    "desc": "A single string that provides a detailed description of the desired image.",
    "file_name": "The name of the file to which the generated image will be saved (include extension)."
  },
  "tts_tool": {
    "content": "The text content that needs to be converted to speech.",
    "speaker": "Optional. One of \"male\", \"female\", \"bria\", or \"alex\". Default is \"female\".",
    "file_name": "Optional. The name of the file to save the audio output without the extension. If omitted, a default name will be generated."
  },
  "write_markdown_tool": {
    "content": "The Markdown formatted text content to be written to the file.",
    "filename": "Optional. The name of the file to which the Markdown content will be written. Default is \"output.md\"."
  },
  "write_html_tool": {
    "content": "The HTML content to be written to the file. Must contain valid HTML structure.",
    "filename": "Optional. The name of the file to which the HTML content will be written. Default is \"output.html\"."
  },
  "search_web_tool": {
    "query": "The search term or phrase to be queried.",
    "num_results": "Optional. The maximum number of search results to return. Default is 3.",
    "source": "Optional. One of \"text\" or \"news\". Default is \"text\"."
  },
  "get_url_content": {
    "url": "The web address of the page to scrape.",
    "timeout": "Optional. Maximum time in seconds to wait for the server to send data. Default is 30.",
    "user_agent": "Optional. The User-Agent string to be used for the HTTP request. Default is \"Mozilla/5.0\"."
  }
}
```

